mapper.sql:
WITH valid_pp AS ( SELECT pp.* FROM lx_purchase_plan pp WHERE pp.status NOT IN (-3, 122, 124) AND pp.create_time IS NOT NULL AND pp.create_time <= #{query.asOf}
AND pp.plan_sn = #{planSn}
AND EXISTS ( SELECT 1 FROM lx_pp_po_sku_ass ass WHERE ass.plan_sn = pp.plan_sn AND ass.order_sn = #{orderSn} )
AND pp.create_time >= #{query.startDate}
AND pp.create_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)
), valid_po AS ( SELECT po.* FROM lx_purchase_order po WHERE po.status NOT IN (-1, 124) AND po.create_time IS NOT NULL AND po.create_time <= #{query.asOf}
AND EXISTS ( SELECT 1 FROM lx_pp_po_sku_ass ass WHERE ass.order_sn = po.order_sn AND ass.plan_sn = #{planSn} )
AND po.order_sn = #{orderSn}
), po_sent_log_ranked AS ( SELECT po.order_sn, bl.id AS sent_log_id, bl.ol_time AS sent_at, bl.realname AS sent_operator, ROW_NUMBER() OVER ( PARTITION BY po.order_sn ORDER BY bl.ol_time ASC, bl.id ASC ) AS rn FROM valid_po po INNER JOIN lx_business_log bl ON bl.business_id = CONCAT('1_', po.order_sn) WHERE bl.ol_type_text = '下单' AND bl.ol_time IS NOT NULL AND bl.ol_time <= #{query.asOf} ), po_sent_log AS ( SELECT order_sn, sent_log_id, sent_at, sent_operator FROM po_sent_log_ranked WHERE rn = 1 ), po_item_facts AS ( SELECT poi.id AS item_id, poi.order_sn, NULLIF(TRIM(poi.sku), '') AS sku, poi.product_name, poi.quantity_real, poi.quantity_entry, poi.quantity_return, poi.quantity_exchange FROM lx_purchase_order_item poi INNER JOIN valid_po po ON po.order_sn = poi.order_sn WHERE poi.is_delete = 0 ), po_items AS ( SELECT pif.order_sn, SUM(GREATEST(COALESCE(pif.quantity_real, 0), 0)) AS purchase_qty, GROUP_CONCAT(DISTINCT pif.sku ORDER BY pif.sku SEPARATOR '、') AS skus, GROUP_CONCAT(DISTINCT NULLIF(TRIM(pif.product_name), '') ORDER BY pif.product_name SEPARATOR '、') AS product_names FROM po_item_facts pif GROUP BY pif.order_sn ), /* PP-PO-SKU 关系唯一由 lx_pp_po_sku_ass 提供（plan_sn×order_sn×sku，带 idx_pp_po_sku 索引）。下游所有 PP×PO 关联一律通过 relation_skus 的 (order_sn, sku) 连接 po_item_facts 确定，不再对 PO item 的 JSON 关联字段做 逐行判定——JSON 函数无法走索引，是明细/列表查询的主要开销。该表和原始 PO item 都没有分摊数量，因此这里只用于确定关联关系，不推算任何 PP 分摊数量。 */ relation_skus AS ( SELECT DISTINCT ass.plan_sn, ass.order_sn, NULLIF(TRIM(ass.sku), '') AS sku FROM lx_pp_po_sku_ass ass INNER JOIN valid_pp pp ON pp.plan_sn = ass.plan_sn INNER JOIN valid_po po ON po.order_sn = ass.order_sn WHERE ass.plan_sn IS NOT NULL AND ass.plan_sn <> '' AND ass.order_sn IS NOT NULL AND ass.order_sn <> '' ), relation_orders AS ( SELECT DISTINCT rs.plan_sn, rs.order_sn FROM relation_skus rs ), receipt_facts AS ( SELECT ro.id AS receipt_id, ro.order_sn AS receipt_sn, pif.order_sn, ro.create_time AS created_at, ro.create_realname AS operator_name, SUM(GREATEST(COALESCE(roi.product_receive_num, 0), 0)) AS receipt_qty FROM lx_receipt_order ro INNER JOIN lx_receipt_order_item roi ON roi.order_sn = ro.order_sn INNER JOIN po_item_facts pif ON pif.item_id = roi.order_item_id WHERE ro.create_time IS NOT NULL AND ro.create_time <= #{query.asOf} GROUP BY ro.id, ro.order_sn, pif.order_sn, ro.create_time, ro.create_realname ), /* 与 receipt_facts 同源，但保留 SKU 维度，供 PO 详情按单个 SKU / PP×PO 限定时的 CR 收货时间线使用；receipt_qty 为该收货单内该 SKU 的收货数量。 */ receipt_sku_facts AS ( SELECT ro.id AS receipt_id, ro.order_sn AS receipt_sn, pif.order_sn, pif.sku, ro.create_time AS created_at, ro.create_realname AS operator_name, SUM(GREATEST(COALESCE(roi.product_receive_num, 0), 0)) AS receipt_qty FROM lx_receipt_order ro INNER JOIN lx_receipt_order_item roi ON roi.order_sn = ro.order_sn INNER JOIN po_item_facts pif ON pif.item_id = roi.order_item_id WHERE ro.create_time IS NOT NULL AND ro.create_time <= #{query.asOf} GROUP BY ro.id, ro.order_sn, pif.order_sn, pif.sku, ro.create_time, ro.create_realname ), receipt_summary AS ( SELECT rf.order_sn, COUNT(DISTINCT rf.receipt_id) AS receipt_count, GROUP_CONCAT(DISTINCT rf.receipt_sn ORDER BY rf.created_at, rf.receipt_id SEPARATOR '||') AS receipt_sns, MIN(rf.created_at) AS first_receipt_at FROM receipt_facts rf GROUP BY rf.order_sn ), /* PO×SKU 维度 CR 收货汇总：PO 详情按单个 SKU 限定时的 CR 单号/单量。与 PO 整单的 receipt_summary 不同，这里只统计含该 SKU 明细行的收货单，避免共享 PO 其他 SKU 的 CR 单被带入。 */ order_sku_receipt_summary AS ( SELECT pif.order_sn, pif.sku, COUNT(DISTINCT ro.id) AS receipt_count, GROUP_CONCAT(DISTINCT ro.order_sn ORDER BY ro.create_time, ro.id SEPARATOR '||') AS receipt_sns FROM po_item_facts pif INNER JOIN lx_receipt_order_item roi ON roi.order_item_id = pif.item_id INNER JOIN lx_receipt_order ro ON ro.order_sn = roi.order_sn WHERE ro.create_time IS NOT NULL AND ro.create_time <= #{query.asOf} GROUP BY pif.order_sn, pif.sku ), /* PP×PO 维度 CR 收货汇总：PO 详情按 PP×PO 关联 SKU 限定时的 CR 单号/单量。口径与 pp_po_item_totals 一致，只统计本 PP 关联 SKU 明细行对应的收货单。 */ pp_po_receipt_summary AS ( SELECT rs.plan_sn, rs.order_sn, COUNT(DISTINCT ro.id) AS receipt_count, GROUP_CONCAT(DISTINCT ro.order_sn ORDER BY ro.create_time, ro.id SEPARATOR '||') AS receipt_sns FROM relation_skus rs INNER JOIN po_item_facts pif ON pif.order_sn = rs.order_sn AND pif.sku <=> rs.sku INNER JOIN lx_receipt_order_item roi ON roi.order_item_id = pif.item_id INNER JOIN lx_receipt_order ro ON ro.order_sn = roi.order_sn WHERE ro.create_time IS NOT NULL AND ro.create_time <= #{query.asOf} GROUP BY rs.plan_sn, rs.order_sn ), valid_ib_items AS ( SELECT ib.id AS inbound_id, ib.order_sn AS inbound_sn, poi.order_sn, poi.item_id AS purchase_item_id, ib.create_time AS created_at, COALESCE(ib.create_realname, ib.opt_realname) AS operator_name, ibi.product_total AS inbound_qty FROM lx_inbound_order ib INNER JOIN lx_inbound_order_item ibi ON ibi.order_sn = ib.order_sn INNER JOIN po_item_facts poi ON poi.item_id = ibi.purchase_item_id AND poi.order_sn = ib.purchase_order_sn WHERE ), ib_per_document AS ( SELECT vii.inbound_id, vii.inbound_sn, vii.order_sn, vii.created_at, MAX(vii.operator_name) AS operator_name, SUM(vii.inbound_qty) AS inbound_qty FROM valid_ib_items vii GROUP BY vii.inbound_id, vii.inbound_sn, vii.order_sn, vii.created_at ), ib_running AS ( SELECT ibd.*, SUM(ibd.inbound_qty) OVER ( PARTITION BY ibd.order_sn ORDER BY ibd.created_at, ibd.inbound_id, ibd.inbound_sn ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_qty FROM ib_per_document ibd ), ib_progress AS ( SELECT ibr.inbound_id, ibr.inbound_sn, ibr.order_sn, ibr.created_at, ibr.operator_name, ibr.inbound_qty, ibr.cumulative_qty FROM ib_running ibr ), /* 达标判定下沉到 PO×SKU（采购明细行）粒度：每条明细行按自身 quantity_real 与自身 累计有效入库(product_total)比较，避免跨 SKU 的 PO 总量互相抹平。PO 在其全部有效 明细行均入库达标后才视为完成，completionAt 取最后一行达标时间；quantity_real≤0 的 行视为无需入库，不阻塞完成。 */ ib_per_document_sku AS ( SELECT vii.order_sn, vii.purchase_item_id, vii.inbound_id, vii.inbound_sn, vii.created_at, SUM(vii.inbound_qty) AS inbound_qty FROM valid_ib_items vii GROUP BY vii.order_sn, vii.purchase_item_id, vii.inbound_id, vii.inbound_sn, vii.created_at ), ib_sku_running AS ( SELECT idsk.*, GREATEST(COALESCE(pif.quantity_real, 0), 0) AS line_qty, SUM(idsk.inbound_qty) OVER ( PARTITION BY idsk.purchase_item_id ORDER BY idsk.created_at, idsk.inbound_id, idsk.inbound_sn ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS line_cumulative_qty FROM ib_per_document_sku idsk INNER JOIN po_item_facts pif ON pif.item_id = idsk.purchase_item_id ), sku_completion AS ( SELECT isr.purchase_item_id, MIN(CASE WHEN isr.line_qty > 0 AND isr.line_cumulative_qty >= isr.line_qty THEN isr.created_at END) AS sku_completion_at, SUBSTRING_INDEX( GROUP_CONCAT( CASE WHEN isr.line_qty > 0 AND isr.line_cumulative_qty >= isr.line_qty THEN isr.inbound_sn END ORDER BY isr.created_at, isr.inbound_id, isr.inbound_sn SEPARATOR '||' ), '||', 1 ) AS sku_completion_inbound_sn FROM ib_sku_running isr GROUP BY isr.purchase_item_id ), /* PO×SKU 粒度达标：供 findOrderSkuLines 的"达标IB"列使用。与上面的 sku_completion （按采购明细行 purchase_item_id）不同，这里按 (order_sn, sku) 聚合，取该 SKU 累计 有效入库首次达到其 quantity_real 合计的那张入库单；quantity_real≤0 的 SKU 不判达标。 */ order_sku_running AS ( SELECT idsk.order_sn, idsk.sku, idsk.inbound_id, idsk.inbound_sn, idsk.created_at, idsk.inbound_qty, SUM(idsk.inbound_qty) OVER ( PARTITION BY idsk.order_sn, idsk.sku ORDER BY idsk.created_at, idsk.inbound_id, idsk.inbound_sn ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_qty FROM ( SELECT vii.order_sn, pif.sku, vii.inbound_id, vii.inbound_sn, vii.created_at, SUM(vii.inbound_qty) AS inbound_qty FROM valid_ib_items vii INNER JOIN po_item_facts pif ON pif.item_id = vii.purchase_item_id GROUP BY vii.order_sn, pif.sku, vii.inbound_id, vii.inbound_sn, vii.created_at ) idsk ), order_sku_target AS ( SELECT pif.order_sn, pif.sku, SUM(GREATEST(COALESCE(pif.quantity_real, 0), 0)) AS line_qty FROM po_item_facts pif GROUP BY pif.order_sn, pif.sku ), order_sku_completion AS ( SELECT osr.order_sn, osr.sku, MIN(CASE WHEN ost.line_qty > 0 AND osr.cumulative_qty >= ost.line_qty THEN osr.created_at END) AS sku_completion_at, SUBSTRING_INDEX( GROUP_CONCAT( CASE WHEN ost.line_qty > 0 AND osr.cumulative_qty >= ost.line_qty THEN osr.inbound_sn END ORDER BY osr.created_at, osr.inbound_id, osr.inbound_sn SEPARATOR '||' ), '||', 1 ) AS sku_completion_inbound_sn FROM order_sku_running osr INNER JOIN order_sku_target ost ON ost.order_sn = osr.order_sn AND ost.sku <=> osr.sku GROUP BY osr.order_sn, osr.sku ), po_completion AS ( SELECT pif.order_sn, CASE WHEN COUNT(DISTINCT CASE WHEN GREATEST(COALESCE(pif.quantity_real, 0), 0) > 0 THEN pif.item_id END) > 0 AND COUNT(DISTINCT CASE WHEN GREATEST(COALESCE(pif.quantity_real, 0), 0) > 0 THEN pif.item_id END) = COUNT(DISTINCT CASE WHEN sc.sku_completion_at IS NOT NULL THEN sc.purchase_item_id END) THEN MAX(sc.sku_completion_at) END AS completion_at, CASE WHEN COUNT(DISTINCT CASE WHEN GREATEST(COALESCE(pif.quantity_real, 0), 0) > 0 THEN pif.item_id END) > 0 AND COUNT(DISTINCT CASE WHEN GREATEST(COALESCE(pif.quantity_real, 0), 0) > 0 THEN pif.item_id END) = COUNT(DISTINCT CASE WHEN sc.sku_completion_at IS NOT NULL THEN sc.purchase_item_id END) THEN SUBSTRING_INDEX( GROUP_CONCAT(sc.sku_completion_inbound_sn ORDER BY sc.sku_completion_at DESC, sc.purchase_item_id SEPARATOR '||'), '||', 1 ) END AS completion_inbound_sn FROM po_item_facts pif LEFT JOIN sku_completion sc ON sc.purchase_item_id = pif.item_id GROUP BY pif.order_sn ), po_ib_summary AS ( SELECT ip.order_sn, COUNT(*) AS inbound_count, GROUP_CONCAT(ip.inbound_sn ORDER BY ip.created_at, ip.inbound_id SEPARATOR '||') AS inbound_sns, MAX(ip.cumulative_qty) AS valid_inbound_qty, pc.completion_at, pc.completion_inbound_sn FROM ib_progress ip LEFT JOIN po_completion pc ON pc.order_sn = ip.order_sn GROUP BY ip.order_sn, pc.completion_at, pc.completion_inbound_sn ), pp_sku_completion AS ( SELECT rs.plan_sn, COUNT(DISTINCT CASE WHEN GREATEST(COALESCE(pif.quantity_real, 0), 0) > 0 THEN pif.item_id END) AS related_sku_line_count, COUNT(DISTINCT CASE WHEN GREATEST(COALESCE(pif.quantity_real, 0), 0) > 0 AND sc.sku_completion_at IS NOT NULL THEN pif.item_id END) AS completed_sku_line_count FROM relation_skus rs INNER JOIN po_item_facts pif ON pif.order_sn = rs.order_sn AND pif.sku <=> rs.sku LEFT JOIN sku_completion sc ON sc.purchase_item_id = pif.item_id GROUP BY rs.plan_sn ), /* PP×PO 维度达标：PP 详情「关联 PO」的达标IB。与 po_completion（PO 整单）不同，这里 按单个 PP 在某 PO 关联的 SKU 判定——共享 PO 时只受本 PP 关联 SKU 影响，不被其他 PP 的 SKU 阻塞；判定口径与 pp_sku_completion 一致，只是细到 PO。 */ pp_po_sku_completion AS ( SELECT rs.plan_sn, rs.order_sn, CASE WHEN COUNT(DISTINCT CASE WHEN GREATEST(COALESCE(pif.quantity_real, 0), 0) > 0 THEN pif.item_id END) > 0 AND COUNT(DISTINCT CASE WHEN GREATEST(COALESCE(pif.quantity_real, 0), 0) > 0 THEN pif.item_id END) = COUNT(DISTINCT CASE WHEN sc.sku_completion_at IS NOT NULL THEN sc.purchase_item_id END) THEN MAX(sc.sku_completion_at) END AS completion_at, CASE WHEN COUNT(DISTINCT CASE WHEN GREATEST(COALESCE(pif.quantity_real, 0), 0) > 0 THEN pif.item_id END) > 0 AND COUNT(DISTINCT CASE WHEN GREATEST(COALESCE(pif.quantity_real, 0), 0) > 0 THEN pif.item_id END) = COUNT(DISTINCT CASE WHEN sc.sku_completion_at IS NOT NULL THEN sc.purchase_item_id END) THEN SUBSTRING_INDEX( GROUP_CONCAT(sc.sku_completion_inbound_sn ORDER BY sc.sku_completion_at DESC, sc.purchase_item_id SEPARATOR '||'), '||', 1 ) END AS completion_inbound_sn FROM relation_skus rs INNER JOIN po_item_facts pif ON pif.order_sn = rs.order_sn AND pif.sku <=> rs.sku LEFT JOIN sku_completion sc ON sc.purchase_item_id = pif.item_id GROUP BY rs.plan_sn, rs.order_sn ), /* PP×PO 维度数量：PP 详情「关联 PO」的采购数量与累计有效入库。共享 PO 时只统计本 PP 关联 SKU，不把其他 PP 的 SKU 数量并入；口径与 pp_po_sku_completion 一致。 */ pp_po_item_totals AS ( SELECT rs.plan_sn, rs.order_sn, SUM(GREATEST(COALESCE(pif.quantity_real, 0), 0)) AS purchase_qty FROM relation_skus rs INNER JOIN po_item_facts pif ON pif.order_sn = rs.order_sn AND pif.sku <=> rs.sku GROUP BY rs.plan_sn, rs.order_sn ), pp_po_inbound_totals AS ( SELECT rs.plan_sn, rs.order_sn, SUM(vii.inbound_qty) AS valid_inbound_qty FROM relation_skus rs INNER JOIN po_item_facts pif ON pif.order_sn = rs.order_sn AND pif.sku <=> rs.sku INNER JOIN valid_ib_items vii ON vii.purchase_item_id = pif.item_id GROUP BY rs.plan_sn, rs.order_sn ), /* PO×SKU 有效 IB 汇总：供 PO 详情按单个 SKU 限定时的单量/单号列表。 */ order_sku_ib_summary AS ( SELECT osr.order_sn, osr.sku, COUNT(DISTINCT osr.inbound_id) AS inbound_count, GROUP_CONCAT(DISTINCT osr.inbound_sn ORDER BY osr.created_at, osr.inbound_id SEPARATOR '||') AS inbound_sns, SUM(osr.inbound_qty) AS valid_inbound_qty FROM order_sku_running osr GROUP BY osr.order_sn, osr.sku ), /* PP×PO 有效 IB 汇总：供 PO 详情按 PP×PO 关联 SKU 限定时的单号列表。 */ pp_po_ib_summary AS ( SELECT rs.plan_sn, rs.order_sn, COUNT(DISTINCT vii.inbound_id) AS inbound_count, GROUP_CONCAT(DISTINCT vii.inbound_sn ORDER BY vii.created_at, vii.inbound_id SEPARATOR '||') AS inbound_sns FROM relation_skus rs INNER JOIN po_item_facts pif ON pif.order_sn = rs.order_sn AND pif.sku <=> rs.sku INNER JOIN valid_ib_items vii ON vii.purchase_item_id = pif.item_id GROUP BY rs.plan_sn, rs.order_sn ), /* PP×PO 有效 IB 入库流水：按 PP×PO 关联 SKU 聚合成每张入库单，累计口径同样限定在 该 PP 关联 SKU 范围内。供 PO 详情（PP×PO 模式）的入库明细与时间线使用。 */ pp_po_ib_running AS ( SELECT per_doc.plan_sn, per_doc.order_sn, per_doc.inbound_id, per_doc.inbound_sn, per_doc.created_at, per_doc.inbound_qty, SUM(per_doc.inbound_qty) OVER ( PARTITION BY per_doc.plan_sn, per_doc.order_sn ORDER BY per_doc.created_at, per_doc.inbound_id, per_doc.inbound_sn ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_qty FROM ( SELECT rs.plan_sn, rs.order_sn, vii.inbound_id, vii.inbound_sn, vii.created_at, SUM(vii.inbound_qty) AS inbound_qty FROM relation_skus rs INNER JOIN po_item_facts pif ON pif.order_sn = rs.order_sn AND pif.sku <=> rs.sku INNER JOIN valid_ib_items vii ON vii.purchase_item_id = pif.item_id GROUP BY rs.plan_sn, rs.order_sn, vii.inbound_id, vii.inbound_sn, vii.created_at ) per_doc ), po_facts_raw AS ( SELECT po.id AS order_id, po.order_sn, pi.skus, pi.product_names, po.status, po.status_text, po.supplier_name AS supplier, po.ware_house_name AS warehouse, po.opt_realname AS buyer, po.settlement_method, CASE WHEN po.settlement_method = 7 THEN 'SPOT' WHEN po.settlement_method = 8 THEN 'MONTHLY' ELSE 'OTHER' END AS settlement_type, CASE WHEN NULLIF(TRIM(po.alibaba_order_sn), '') IS NOT NULL THEN '1688' ELSE 'NORMAL' END AS source_type, po.create_time AS created_at, po.auditor_time AS approval_at, psl.sent_log_id, psl.sent_at, psl.sent_operator, pi.purchase_qty, COALESCE(rs.receipt_sns, '') AS receipt_sns, COALESCE(rs.receipt_count, 0) AS receipt_count, rs.first_receipt_at, COALESCE(pis.inbound_sns, '') AS inbound_sns, COALESCE(pis.inbound_count, 0) AS inbound_count, COALESCE(pis.valid_inbound_qty, 0) AS valid_inbound_qty, pis.completion_inbound_sn, pis.completion_at, CASE WHEN psl.sent_at IS NULL THEN NULL ELSE TIMESTAMPDIFF(HOUR, psl.sent_at, COALESCE(pis.completion_at, #{query.asOf})) END AS delivery_hours FROM valid_po po LEFT JOIN po_sent_log psl ON psl.order_sn = po.order_sn LEFT JOIN po_items pi ON pi.order_sn = po.order_sn LEFT JOIN receipt_summary rs ON rs.order_sn = po.order_sn LEFT JOIN po_ib_summary pis ON pis.order_sn = po.order_sn ), po_facts AS ( SELECT pofr.*, CASE WHEN pofr.sent_at IS NULL THEN 'PENDING' WHEN pofr.completion_at IS NOT NULL AND pofr.completion_at <= DATE_ADD(pofr.sent_at, INTERVAL 360 HOUR) THEN 'COMPLETED_WITHIN_SLA' WHEN pofr.completion_at IS NOT NULL THEN 'COMPLETED_OVER_SLA' WHEN #{query.asOf} >= DATE_ADD(pofr.sent_at, INTERVAL 360 HOUR) THEN 'IN_TRANSIT_OVERDUE' ELSE 'IN_TRANSIT' END AS delivery_status, CASE WHEN pofr.completion_at IS NOT NULL THEN 'COMPLETED' WHEN pofr.inbound_count > 0 AND pofr.completion_at IS NULL THEN 'IB_CREATE' WHEN pofr.receipt_count > 0 AND pofr.inbound_count = 0 THEN 'CR_RECEIPT' WHEN pofr.status = 3 THEN 'PO_CREATE' WHEN pofr.status = 121 THEN 'PO_APPROVAL' WHEN pofr.status = 1 THEN 'SUPPLIER_SENT' WHEN pofr.sent_at IS NOT NULL AND pofr.settlement_method = 7 AND pofr.receipt_count = 0 THEN 'FINANCE_PAYMENT' ELSE CAST(NULL AS CHAR) END AS current_node, CASE WHEN pofr.completion_at IS NOT NULL THEN 9 WHEN pofr.inbound_count > 0 AND pofr.completion_at IS NULL THEN 8 WHEN pofr.receipt_count > 0 AND pofr.inbound_count = 0 THEN 7 WHEN pofr.status = 3 THEN 3 WHEN pofr.status = 121 THEN 4 WHEN pofr.status = 1 THEN 5 WHEN pofr.sent_at IS NOT NULL AND pofr.settlement_method = 7 AND pofr.receipt_count = 0 THEN 6 ELSE CAST(NULL AS SIGNED) END AS node_rank FROM po_facts_raw pofr ), /* 原始数据不包含 PP 分摊数量，所有分摊字段固定为不可用。 */ plan_order_allocation AS ( SELECT rel.plan_sn, rel.order_sn, 0 AS allocation_available, CAST(NULL AS SIGNED) AS allocated_qty, CAST(NULL AS SIGNED) AS inbound_qty FROM relation_orders rel ), plan_allocation AS ( SELECT rel.plan_sn, 0 AS allocation_available, CAST(NULL AS SIGNED) AS allocated_qty, CAST(NULL AS SIGNED) AS inbound_qty FROM relation_orders rel GROUP BY rel.plan_sn ), order_allocation AS ( SELECT rel.order_sn, COUNT(DISTINCT rel.plan_sn) AS related_plan_count, 0 AS allocation_available, CAST(NULL AS SIGNED) AS allocated_qty FROM relation_orders rel GROUP BY rel.order_sn ), plan_item_totals AS ( SELECT rs.plan_sn, SUM(pif.quantity_real) AS purchase_qty, SUM(pif.quantity_entry) AS inbound_qty, SUM(COALESCE(pif.quantity_return, 0)) AS returned_qty, SUM(COALESCE(pif.quantity_exchange, 0)) AS exchange_qty FROM relation_skus rs INNER JOIN po_item_facts pif ON pif.order_sn = rs.order_sn AND pif.sku <=> rs.sku GROUP BY rs.plan_sn ), plan_rollup AS ( SELECT pp.plan_sn, pp.product_name, pp.sku, pp.status_text, pp.approval_status, pp.supplier_name AS pp_supplier, pp.create_time AS created_at, pp.approval_time AS approval_at, CAST(pp.quantity_plan AS SIGNED) AS plan_qty, COALESCE(MAX(ppt.purchase_qty), 0) AS purchase_qty, COALESCE(MAX(ppt.inbound_qty), 0) AS po_inbound_qty, COALESCE(MAX(ppt.returned_qty), 0) AS returned_qty, COALESCE(MAX(ppt.exchange_qty), 0) AS exchange_qty, COUNT(DISTINCT pof.order_sn) AS related_order_count, GROUP_CONCAT(DISTINCT pof.order_sn ORDER BY pof.order_sn SEPARATOR '||') AS order_sns, GROUP_CONCAT(DISTINCT NULLIF(TRIM(pof.buyer), '') ORDER BY pof.buyer SEPARATOR '||') AS buyers, GROUP_CONCAT(DISTINCT NULLIF(TRIM(pof.supplier), '') ORDER BY pof.supplier SEPARATOR '||') AS suppliers, GROUP_CONCAT(DISTINCT NULLIF(TRIM(pof.warehouse), '') ORDER BY pof.warehouse SEPARATOR '||') AS warehouses, GROUP_CONCAT(DISTINCT NULLIF(TRIM(pof.skus), '') ORDER BY pof.skus SEPARATOR '||') AS related_skus, GROUP_CONCAT(DISTINCT NULLIF(TRIM(pof.receipt_sns), '') ORDER BY pof.receipt_sns SEPARATOR '||') AS receipt_sns, GROUP_CONCAT(DISTINCT NULLIF(TRIM(pof.inbound_sns), '') ORDER BY pof.inbound_sns SEPARATOR '||') AS inbound_sns, MAX(pof.created_at) AS last_po_created_at, MIN(pof.sent_at) AS first_sent_at, TIMESTAMPDIFF(HOUR, pp.create_time, COALESCE(MAX(pof.created_at), #{query.asOf})) AS order_lead_hours, MIN(pof.node_rank) AS earliest_po_node_rank, MAX(pof.delivery_hours) AS max_delivery_hours, MIN(pof.completion_at) AS first_completion_at, SUBSTRING_INDEX( GROUP_CONCAT( CASE WHEN pof.completion_at IS NOT NULL THEN pof.delivery_status END ORDER BY pof.completion_at, pof.order_id SEPARATOR '||' ), '||', 1 ) AS first_completion_delivery_status, SUM(CASE WHEN pof.completion_at IS NOT NULL THEN 1 ELSE 0 END) AS completed_order_count, SUM(CASE WHEN pof.status_text = '已完成' THEN 1 ELSE 0 END) AS completed_status_order_count, SUM(CASE WHEN pof.delivery_status = 'PENDING' THEN 1 ELSE 0 END) AS pending_order_count, SUM(CASE WHEN pof.delivery_status = 'IN_TRANSIT_OVERDUE' THEN 1 ELSE 0 END) AS transit_overdue_count, SUM(CASE WHEN pof.delivery_status = 'COMPLETED_OVER_SLA' THEN 1 ELSE 0 END) AS completed_over_sla_count, MAX(pa.allocation_available) AS allocation_evaluable, MAX(pa.allocated_qty) AS allocated_qty, MAX(pa.inbound_qty) AS allocated_inbound_qty FROM valid_pp pp LEFT JOIN relation_orders rel ON rel.plan_sn = pp.plan_sn LEFT JOIN po_facts pof ON pof.order_sn = rel.order_sn LEFT JOIN plan_item_totals ppt ON ppt.plan_sn = pp.plan_sn LEFT JOIN plan_allocation pa ON pa.plan_sn = pp.plan_sn GROUP BY pp.plan_sn, pp.product_name, pp.sku, pp.status_text, pp.approval_status, pp.supplier_name, pp.create_time, pp.approval_time, pp.quantity_plan ), plan_facts AS ( SELECT pr.*, CASE WHEN pr.last_po_created_at IS NOT NULL AND pr.last_po_created_at < DATE_ADD(pr.created_at, INTERVAL 24 HOUR) THEN 'TIMELY' WHEN pr.last_po_created_at IS NULL AND #{query.asOf} < DATE_ADD(pr.created_at, INTERVAL 24 HOUR) THEN 'ORDERING' ELSE 'OVERDUE' END AS order_timeliness, CASE WHEN pr.last_po_created_at IS NOT NULL THEN 1 ELSE 0 END AS order_coverage_confirmed, CASE WHEN pr.status_text = '已完成' AND pr.related_order_count = 0 THEN 'COMPLETED' WHEN pr.related_order_count > 0 AND psc.related_sku_line_count > 0 AND psc.completed_sku_line_count = psc.related_sku_line_count THEN 'COMPLETED' WHEN pr.related_order_count > 0 AND pr.completed_order_count = pr.related_order_count THEN 'COMPLETED' WHEN pr.related_order_count > 0 AND pr.completed_status_order_count = pr.related_order_count THEN 'COMPLETED' WHEN pr.status_text = '待审批' THEN 'PP_CREATE' WHEN pr.status_text = '待采购' THEN 'PP_APPROVAL' WHEN pr.related_order_count = 0 THEN 'PP_APPROVAL' WHEN pr.earliest_po_node_rank = 3 THEN 'PO_CREATE' WHEN pr.earliest_po_node_rank = 4 THEN 'PO_APPROVAL' WHEN pr.earliest_po_node_rank = 5 THEN 'SUPPLIER_SENT' WHEN pr.earliest_po_node_rank = 6 THEN 'FINANCE_PAYMENT' WHEN pr.earliest_po_node_rank = 7 THEN 'CR_RECEIPT' WHEN pr.earliest_po_node_rank = 8 THEN 'IB_CREATE' ELSE CAST(NULL AS CHAR) END AS current_node, CASE WHEN pr.related_order_count = 0 THEN 'PENDING' WHEN pr.completed_order_count > 0 AND pr.first_completion_delivery_status = 'COMPLETED_OVER_SLA' THEN 'COMPLETED_OVER_SLA' WHEN pr.completed_order_count > 0 THEN 'COMPLETED_WITHIN_SLA' WHEN pr.completed_over_sla_count > 0 OR pr.transit_overdue_count > 0 THEN 'IN_TRANSIT_OVERDUE' WHEN pr.pending_order_count > 0 THEN 'PENDING' ELSE 'IN_TRANSIT' END AS delivery_status, CASE WHEN pr.plan_qty > 0 AND pr.allocation_evaluable = 1 THEN 1 ELSE 0 END AS allocation_available, pr.po_inbound_qty AS inbound_qty, CASE WHEN pr.purchase_qty > 0 THEN LEAST( CAST(100 AS DECIMAL(18, 4)), CAST(pr.po_inbound_qty * 100.0 / pr.purchase_qty AS DECIMAL(18, 4)) ) ELSE NULL END AS achievement_rate FROM plan_rollup pr LEFT JOIN pp_sku_completion psc ON psc.plan_sn = pr.plan_sn ), filtered_relation_orders AS ( SELECT DISTINCT rel.plan_sn, rel.order_sn FROM relation_orders rel INNER JOIN valid_pp pp ON pp.plan_sn = rel.plan_sn INNER JOIN po_facts pof ON pof.order_sn = rel.order_sn WHERE 1 = 1
AND ( pp.plan_sn LIKE CONCAT('%', #{query.keyword}, '%') OR pp.sku LIKE CONCAT('%', #{query.keyword}, '%') OR pp.product_name LIKE CONCAT('%', #{query.keyword}, '%') OR pp.supplier_name LIKE CONCAT('%', #{query.keyword}, '%') OR pof.order_sn LIKE CONCAT('%', #{query.keyword}, '%') OR pof.skus LIKE CONCAT('%', #{query.keyword}, '%') OR pof.product_names LIKE CONCAT('%', #{query.keyword}, '%') OR pof.supplier LIKE CONCAT('%', #{query.keyword}, '%') OR pof.receipt_sns LIKE CONCAT('%', #{query.keyword}, '%') OR pof.inbound_sns LIKE CONCAT('%', #{query.keyword}, '%') )
AND pof.buyer = #{query.buyer}
AND pof.supplier = #{query.supplier}
AND pof.warehouse = #{query.warehouse}
AND pof.delivery_status = #{query.deliveryStatus}
), filtered_plan_projection AS ( SELECT fro.plan_sn, COUNT(DISTINCT pof.order_sn) AS related_order_count, GROUP_CONCAT(DISTINCT pof.order_sn ORDER BY pof.order_sn SEPARATOR '||') AS order_sns, GROUP_CONCAT(DISTINCT NULLIF(TRIM(pof.buyer), '') ORDER BY pof.buyer SEPARATOR '||') AS buyers, GROUP_CONCAT(DISTINCT NULLIF(TRIM(pof.supplier), '') ORDER BY pof.supplier SEPARATOR '||') AS suppliers, GROUP_CONCAT(DISTINCT NULLIF(TRIM(pof.warehouse), '') ORDER BY pof.warehouse SEPARATOR '||') AS warehouses FROM filtered_relation_orders fro INNER JOIN po_facts pof ON pof.order_sn = fro.order_sn GROUP BY fro.plan_sn )

mapper.select:
, filtered_plans AS ( SELECT pf.* FROM plan_facts pf WHERE 1 = 1
), node_scoped_plans AS ( SELECT pf.* FROM plan_facts pf WHERE 1 = 1
), latest_sync AS ( SELECT ( SELECT t.end_time FROM lx_sync_task t WHERE t.task_type IN ('plan', 'order+plan') AND t.status = 'success' AND t.end_time IS NOT NULL ORDER BY t.end_time DESC, t.id DESC LIMIT 1 ) AS plan_completed_at, ( SELECT t.end_time FROM lx_sync_task t WHERE t.task_type IN ('order', 'order+plan') AND t.status = 'success' AND t.end_time IS NOT NULL ORDER BY t.end_time DESC, t.id DESC LIMIT 1 ) AS order_completed_at ), summary_counts AS ( SELECT (SELECT COUNT(*) FROM node_scoped_plans) AS total, (SELECT COALESCE(SUM(current_node = 'PP_CREATE'), 0) FROM filtered_plans) AS pp_create_count, (SELECT COALESCE(SUM(current_node = 'PP_APPROVAL'), 0) FROM filtered_plans) AS pp_approval_count, (SELECT COALESCE(SUM(current_node = 'PO_CREATE'), 0) FROM filtered_plans) AS po_create_count, (SELECT COALESCE(SUM(current_node = 'PO_APPROVAL'), 0) FROM filtered_plans) AS po_approval_count, (SELECT COALESCE(SUM(current_node = 'SUPPLIER_SENT'), 0) FROM filtered_plans) AS supplier_sent_count, (SELECT COALESCE(SUM(current_node = 'FINANCE_PAYMENT'), 0) FROM filtered_plans) AS finance_payment_count, (SELECT COALESCE(SUM(current_node = 'CR_RECEIPT'), 0) FROM filtered_plans) AS receipt_count, (SELECT COALESCE(SUM(current_node = 'IB_CREATE'), 0) FROM filtered_plans) AS inbound_create_count, (SELECT COALESCE(SUM(current_node = 'COMPLETED'), 0) FROM filtered_plans) AS completed_count, (SELECT COALESCE(SUM(order_timeliness = 'OVERDUE'), 0) FROM node_scoped_plans) AS order_overdue_count, ( SELECT COUNT(DISTINCT selected_pf.plan_sn) FROM node_scoped_plans selected_pf INNER JOIN filtered_relation_orders fro ON fro.plan_sn = selected_pf.plan_sn INNER JOIN po_facts pof ON pof.order_sn = fro.order_sn WHERE pof.delivery_status IN ('IN_TRANSIT_OVERDUE', 'COMPLETED_OVER_SLA') ) AS delivery_overdue_count ) SELECT sc.*, CASE WHEN ls.plan_completed_at IS NOT NULL AND ls.order_completed_at IS NOT NULL THEN 'success' ELSE 'incomplete' END AS sync_status, CASE WHEN ls.plan_completed_at IS NOT NULL AND ls.order_completed_at IS NOT NULL THEN LEAST(ls.plan_completed_at, ls.order_completed_at) ELSE NULL END AS data_updated_at FROM summary_counts sc CROSS JOIN latest_sync ls


SELECT pf.*
FROM plan_facts pf
WHERE pf.plan_sn = #{planSn}

mapper.sql:
SELECT CONCAT('PP_APPROVAL_', pp.id) AS event_id, 'PP' AS source_type, pp.plan_sn AS source_sn, pp.approval_time AS event_time, 'PP 最终审批' AS title, CONCAT('PP ', pp.plan_sn, ' 审批通过') AS description, pp.approver AS operator_name, CAST(NULL AS SIGNED) AS quantity, CAST(NULL AS SIGNED) AS cumulative_quantity FROM
relation_skus relation_orders
rel INNER JOIN valid_pp pp ON pp.plan_sn = rel.plan_sn WHERE rel.order_sn = #{orderSn} AND rel.sku <=> #{sku} AND pp.approval_time IS NOT NULL AND pp.approval_time <= #{query.asOf} AND rel.plan_sn = #{planSn} UNION ALL SELECT CONCAT('PO_CREATE_', po.id), 'PO', po.order_sn, po.create_time, 'PO 创建', '', po.opt_realname, NULL, NULL FROM valid_po po WHERE po.order_sn = #{orderSn} UNION ALL SELECT CONCAT('PO_APPROVAL_', po.id), 'PO', po.order_sn, po.auditor_time, 'PO 审批', 'PO 审批通过', po.auditor_realname, NULL, NULL FROM valid_po po WHERE po.order_sn = #{orderSn} AND po.auditor_time IS NOT NULL UNION ALL SELECT CONCAT('PO_SENT_', pof.sent_log_id), 'PO', pof.order_sn, pof.sent_at, '下发供应商', CASE WHEN NULLIF(TRIM(pof.supplier), '') IS NULL THEN '' ELSE CONCAT('供应商：', pof.supplier) END, COALESCE(pof.sent_operator, pof.buyer), NULL, NULL FROM po_facts pof WHERE pof.order_sn = #{orderSn} AND pof.sent_at IS NOT NULL UNION ALL SELECT CONCAT('PAY_', rfo.id), 'PAYMENT', rfo.order_sn, COALESCE(CAST(rfo.real_pay_time AS DATETIME), rfo.apply_time), CASE WHEN rfo.real_pay_time IS NOT NULL THEN '付款' ELSE '请款' END, CASE WHEN rfo.real_pay_time IS NOT NULL THEN '付款完成' ELSE '请款已提交' END, COALESCE(rfo.pay_user, rfo.apply_user), NULL, NULL FROM lx_request_funds_order_item rfoi INNER JOIN lx_request_funds_order rfo ON rfo.order_sn = rfoi.order_sn WHERE rfoi.business_sn = #{orderSn} AND rfo.status NOT IN (3, 122, 124) AND COALESCE(CAST(rfo.real_pay_time AS DATETIME), rfo.apply_time) <= #{query.asOf} UNION ALL
SELECT CONCAT('CR_', rsf.receipt_id), 'CR', rsf.receipt_sn, rsf.created_at, 'CR 收货', '', rsf.operator_name, rsf.receipt_qty, NULL FROM receipt_sku_facts rsf WHERE rsf.order_sn = #{orderSn} AND rsf.sku <=> #{sku}
SELECT CONCAT('CR_', rsf.receipt_id), 'CR', rsf.receipt_sn, MAX(rsf.created_at), 'CR 收货', '', MAX(rsf.operator_name), SUM(rsf.receipt_qty), NULL FROM ( SELECT DISTINCT pif.order_sn, pif.sku FROM relation_skus rs INNER JOIN po_item_facts pif ON pif.order_sn = rs.order_sn AND pif.sku <=> rs.sku WHERE rs.plan_sn = #{planSn} AND rs.order_sn = #{orderSn} ) assoc INNER JOIN receipt_sku_facts rsf ON rsf.order_sn = assoc.order_sn AND rsf.sku <=> assoc.sku GROUP BY rsf.receipt_id, rsf.receipt_sn
SELECT CONCAT('CR_', rf.receipt_id), 'CR', rf.receipt_sn, rf.created_at, 'CR 收货', '', rf.operator_name, rf.receipt_qty, NULL FROM receipt_facts rf WHERE rf.order_sn = #{orderSn}
UNION ALL
SELECT CONCAT('IB_', osr.inbound_id), 'IB', osr.inbound_sn, osr.created_at, '有效 IB 创建', CASE WHEN osc.sku_completion_inbound_sn = osr.inbound_sn AND osc.sku_completion_at = osr.created_at THEN '累计达到采购数量，采购流程完成' ELSE '' END, NULL, osr.inbound_qty, osr.cumulative_qty FROM order_sku_running osr LEFT JOIN order_sku_completion osc ON osc.order_sn = osr.order_sn AND osc.sku <=> osr.sku WHERE osr.order_sn = #{orderSn} AND osr.sku <=> #{sku}
SELECT CONCAT('IB_', ppir.inbound_id), 'IB', ppir.inbound_sn, ppir.created_at, '有效 IB 创建', CASE WHEN ppc.completion_inbound_sn = ppir.inbound_sn AND ppc.completion_at = ppir.created_at THEN '累计达到采购数量，采购流程完成' ELSE '' END, NULL, ppir.inbound_qty, ppir.cumulative_qty FROM pp_po_ib_running ppir LEFT JOIN pp_po_sku_completion ppc ON ppc.plan_sn = ppir.plan_sn AND ppc.order_sn = ppir.order_sn WHERE ppir.plan_sn = #{planSn} AND ppir.order_sn = #{orderSn}
SELECT CONCAT('IB_', ip.inbound_id), 'IB', ip.inbound_sn, ip.created_at, '有效 IB 创建', CASE WHEN pis.completion_inbound_sn = ip.inbound_sn AND pis.completion_at = ip.created_at THEN '累计达到采购数量，采购流程完成' ELSE '' END, ip.operator_name, ip.inbound_qty, ip.cumulative_qty FROM ib_progress ip LEFT JOIN po_ib_summary pis ON pis.order_sn = ip.order_sn WHERE ip.order_sn = #{orderSn}
